/// "Fuel PIVXie" donation art: square 1024 px WebPs cut from the designs
/// by asset_sources/donation/: the hooded PIVXie when `shielded`, the
/// translucent one otherwise.
class _DONATION {
  const _DONATION();

  static const _path = "assets/donation/";

  /// The [usd] dollar tier (1, 5, 10, 20, 50 or 100).
  String tier(int usd, {required bool shielded}) =>
      "$_path${shielded ? "private" : "public"}_t$usd.webp";

  /// After a donation: PIVXie holding a "THANK YOU!" sign.
  String thanks({required bool shielded}) =>
      "$_path${shielded ? "private" : "public"}_thanks.webp";
}

/// The PIVXie mascot (the Void Pixie). PNGs with 1.5x-4.0x density
/// variants: the privacy choice at 140 logical px, the screen artwork
/// within 280.
class _PERSONA {
  const _PERSONA();

  static const _path = "assets/persona/";

  /// "Easy Crypto": external calls on.
  String get public => "${_path}pivxie_public.png";

  /// "Incognito": external calls off.
  String get private => "${_path}pivxie_private.png";

  /// Holding a "WELCOME" banner: the first screen.
  String get welcome => "${_path}pivxie_welcome.png";

  /// Holding a PIVX wallet: create or restore a wallet.
  String get addWallet => "${_path}pivxie_add_wallet.png";

  /// Looping animation (animated WebP, 960x540) while a transaction is
  /// built and sent.
  String get txSend => "${_path}pivxie_tx_send.webp";

  /// [txSend]'s sound (AAC, as long as one loop of the animation).
  String get txSendSound => "${_path}pivxie_tx_send.m4a";
}

